       --accent: #2563eb;
       --accent-strong: #1d4ed8;
       --danger: #dc2626;
       --danger-strong: #b91c1c;
       --focus: #0f62fe;
       --shadow: 0 24px 60px -30px #0f172a33;
       --shadow-soft: 0 8px 24px -14px #0f172a26;
       --radius-xl: 28px;
       --radius-lg: 20px;
       --radius-md: 14px;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       font: 16px/1.5 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, #dbeafe 0, #eff6ff 24%, transparent 55%),
         linear-gradient(180deg, var(--bg-alt), var(--bg));
       min-height: 100vh;
     }

     img {
       display: block;
       max-width: 100%;
     }

     a,
     button {
       font: inherit;
     }

     button {
       border: 0;
       border-radius: 999px;
       cursor: pointer;
       transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease, color 140ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:active {
       transform: translateY(0);
     }

     :focus {
       outline: none;
     }

     :focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--surface);
       color: var(--text);
       text-decoration: none;
       box-shadow: var(--shadow-soft);
       transform: translateY(-180%);
       transition: transform 160ms ease;
       z-index: 20;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page {
       width: min(1120px, calc(100% - 2rem));
       margin: 0 auto;
       padding: 5rem 0 3rem;
     }

     .hero {
       margin-bottom: 1.5rem;
     }

     .eyebrow {
       margin: 0 0 0.5rem;
       text-transform: uppercase;
       letter-spacing: 0.12em;
       font-size: 0.76rem;
       font-weight: 700;
       color: var(--accent-strong);
     }

     h1,
     h2,
     p {
       margin: 0;
     }

     h1 {
       font-size: clamp(2.2rem, 4vw, 4rem);
       line-height: 1.04;
       letter-spacing: -0.04em;
       max-width: 12ch;
     }

     .lead {
       margin-top: 0.9rem;
       max-width: 52ch;
       font-size: 1.05rem;
       color: var(--muted);
     }

     .preview-card,
     .empty-state {
       background: var(--surface);
       border: 1px solid var(--border);
       border-radius: var(--radius-xl);
       box-shadow: var(--shadow);
     }

     .preview-card {
       display: grid;
       grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.9fr);
       gap: 1.5rem;
       padding: 1.25rem;
       align-items: stretch;
     }

     .media-frame {
       overflow: hidden;
       border-radius: calc(var(--radius-xl) - 8px);
       background: linear-gradient(180deg, #dbeafe, #bfdbfe);
       min-height: 420px;
       border: 1px solid var(--border);
     }

     .media-frame img {
       width: 100%;
       height: 100%;
       object-fit: cover;
     }

     .preview-body {
       display: flex;
       flex-direction: column;
       gap: 1.25rem;
       padding: 0.75rem 0.25rem 0.75rem 0.1rem;
     }

     .meta {
       display: grid;
       gap: 0.35rem;
     }

     .meta h2 {
       font-size: 1.5rem;
       line-height: 1.1;
       letter-spacing: -0.03em;
     }

     .meta p {
       color: var(--muted);
     }

     .description {
       color: #334155;
       max-width: 34ch;
     }

     .actions {
       margin-top: auto;
       display: grid;
       gap: 0.9rem;
     }

     .trigger,
     .secondary,
     .danger {
       min-height: 3rem;
       padding: 0.85rem 1.25rem;
       font-weight: 700;
     }

     .trigger {
       width: fit-content;
       color: #fff;
       background: linear-gradient(180deg, var(--danger), var(--danger-strong));
       box-shadow: 0 14px 28px -18px #b91c1c99;
     }

     .trigger:hover {
       background: linear-gradient(180deg, #ef4444, var(--danger));
     }

     .hint {
       color: var(--muted);
       font-size: 0.95rem;
       max-width: 28ch;
     }

     .empty-state {
       margin-top: 1.25rem;
       padding: 2rem;
       display: grid;
       gap: 0.75rem;
       max-width: 42rem;
     }

     .empty-state h2 {
       font-size: 1.6rem;
       letter-spacing: -0.03em;
     }

     .empty-state p {
       color: var(--muted);
       max-width: 42ch;
     }

     .dialog-shell {
       width: min(100%, 34rem);
       border: 1px solid var(--border);
       border-radius: 24px;
       padding: 0;
       box-shadow: var(--shadow);
       background: var(--surface);
       color: var(--text);
       max-height: calc(100vh - 2rem);
       overflow: auto;
     }

     .dialog-shell::backdrop {
       background: #0f172acc;
       backdrop-filter: blur(10px);
     }

     .dialog-card {
       padding: 1.5rem;
       display: grid;
       gap: 1.4rem;
     }

     .dialog-eyebrow {
       display: inline-flex;
       width: fit-content;
       margin-bottom: 0.6rem;
       padding: 0.38rem 0.72rem;
       border-radius: 999px;
       background: #fee2e2;
       color: var(--danger-strong);
       font-size: 0.78rem;
       font-weight: 800;
       letter-spacing: 0.12em;
       text-transform: uppercase;
     }

     .dialog-title {
       font-size: 1.4rem;
       line-height: 1.15;
       letter-spacing: -0.03em;
       margin-bottom: 0.5rem;
     }

     .dialog-copy p {
       color: var(--muted);
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       flex-wrap: wrap;
       gap: 0.75rem;
     }

     .secondary {
       background: var(--surface-strong);
       color: var(--text);
       border: 1px solid var(--border);
     }

     .secondary:hover {
       background: #e2e8f0;
     }

     .danger {
       background: linear-gradient(180deg, var(--danger), var(--danger-strong));
       color: #fff;
       box-shadow: 0 14px 28px -20px #b91c1c99;
     }

     .danger:hover {
       background: linear-gradient(180deg, #ef4444, var(--danger));
     }

     .sr-only {
       position: absolute;
       width: 1px;
       height: 1px;
       padding: 0;
       margin: -1px;
       overflow: hidden;
       clip: rect(0, 0, 0, 0);
       white-space: nowrap;
       border: 0;
     }

     @media (max-width: 900px) {
       .preview-card {
         grid-template-columns: 1fr;
       }

       .media-frame {
         min-height: 320px;
       }
     }

     @media (max-width: 640px) {
       .page {
         width: min(100% - 1rem, 1120px);
         padding-top: 4rem;
       }

       .preview-card {
         padding: 1rem;
       }

       .dialog-card {
         padding: 1.25rem;
       }

       .dialog-actions,
       .actions {
         display: grid;
       }

       .trigger,
       .secondary,
       .danger {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       :root {
         --bg: Canvas;
         --bg-alt: Canvas;
         --surface: Canvas;
         --surface-strong: Canvas;
         --text: CanvasText;
         --muted: CanvasText;
         --border: ButtonBorder;
         --border-strong: ButtonBorder;
         --accent: LinkText;
         --accent-strong: LinkText;
         --danger: ButtonText;
         --danger-strong: ButtonText;
         --focus: Highlight;
         --shadow: none;
         --shadow-soft: none;
       }

       body {
         background: Canvas;
       }

       .preview-card,
       .empty-state,
       .dialog-shell,
       .secondary,
       .trigger,
       .danger {
         forced-color-adjust: auto;
         border: 1px solid ButtonBorder;
         box-shadow: none;
       }

       .trigger,
       .danger {
         background: ButtonFace;
         color: ButtonText;
       }

       .secondary {
         background: ButtonFace;
         color: ButtonText;
       }

       .dialog-shell::backdrop {
         background: Canvas;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <div class="page">
     <header class="hero">
       <p class="eyebrow">Library preview</p>
       <h1>Image preview</h1>
       <p class="lead">Review the image before deciding whether to keep it in your library.</p>
     </header>

     <main id="maincontent" tabindex="-1">
       <section class="preview-card" id="preview-card" aria-labelledby="preview-title">
         <div class="media-frame">
           <img
             alt="Warm abstract landscape preview with a glowing sun and layered mountains"
             src="data:image/svg+xml;base64,"
           >
         </div>

         <div class="preview-body">
           <div class="meta">
             <h2 id="preview-title">Sunrise over the ridge</h2>
             <p>Uploaded 2 hours ago &middot; 4.8 MB</p>
           </div>

           <p class="description">A warm landscape with a bright horizon and layered mountains. Use the button below to remove it from your library.</p>

           <div class="actions">
             <button
               type="button"
               class="trigger"
               id="open-delete-dialog"
               aria-haspopup="dialog"
               aria-controls="delete-dialog"
               aria-expanded="false"
             >
               Delete image
             </button>
             <p class="hint">This action removes the image from your library.</p>
           </div>
         </div>
       </section>

       <section class="empty-state" id="empty-state" tabindex="-1" hidden>
         <h2>Image deleted</h2>
         <p>The image has been removed from your library.</p>
       </section>

       <p id="status" class="sr-only" role="status" aria-live="polite" aria-atomic="true"></p>
     </main>
   </div>

   <dialog class="dialog-shell" id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
     <form class="dialog-card" method="dialog">
       <div class="dialog-copy">
         <span class="dialog-eyebrow">Delete from library</span>
         <h2 class="dialog-title" id="delete-title">Delete “Sunrise over the ridge”?</h2>
         <p id="delete-desc">This will permanently remove the image from your library. This action can't be undone.</p>
       </div>

       <div class="dialog-actions">
         <button type="submit" class="secondary" value="cancel" id="cancel-delete" autofocus>Cancel</button>
         <button type="submit" class="danger" value="delete">Delete image</button>
       </div>
     </form>
   </dialog>

   <script>
     const trigger = document.getElementById('open-delete-dialog');
     const dialog = document.getElementById('delete-dialog');
     const cancelButton = document.getElementById('cancel-delete');
     const previewCard = document.getElementById('preview-card');
     const emptyState = document.getElementById('empty-state');
     const status = document.getElementById('status');

     function openDeleteDialog() {
       if (dialog.open) {
         return;
       }

       if (typeof dialog.showModal === 'function') {
         dialog.showModal();
       } else {
         dialog.setAttribute('open', '');
       }

       trigger.setAttribute('aria-expanded', 'true');
       cancelButton.focus();
     }

     trigger.addEventListener('click', openDeleteDialog);

     dialog.addEventListener('close', () => {
       trigger.setAttribute('aria-expanded', 'false');

       if (dialog.returnValue === 'delete') {
         status.textContent = 'Image deleted from your library.';
         emptyState.hidden = false;
         emptyState.focus({ preventScroll: true });
         previewCard.hidden = true;
       }
     });
   </script>
 </body>
 </html>

