<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="page">
    <header class="hero">
      <p class="eyebrow">Library preview</p>
      <h1>Image preview</h1>
      <p class="lead">Review the image before deciding whether to keep it in your library.</p>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="preview-card" id="preview-card" aria-labelledby="preview-title">
        <div class="media-frame">
          <img
            alt="Warm abstract landscape preview with a glowing sun and layered mountains"
            src="data:image/svg+xml;base64,"
          >
        </div>

        <div class="preview-body">
          <div class="meta">
            <h2 id="preview-title">Sunrise over the ridge</h2>
            <p>Uploaded 2 hours ago &middot; 4.8 MB</p>
          </div>

          <p class="description">A warm landscape with a bright horizon and layered mountains. Use the button below to remove it from your library.</p>

          <div class="actions">
            <button
              type="button"
              class="trigger"
              id="open-delete-dialog"
              aria-haspopup="dialog"
              aria-controls="delete-dialog"
              aria-expanded="false"
            >
              Delete image
            </button>
            <p class="hint">This action removes the image from your library.</p>
          </div>
        </div>
      </section>

      <section class="empty-state" id="empty-state" tabindex="-1" hidden>
        <h2>Image deleted</h2>
        <p>The image has been removed from your library.</p>
      </section>

      <p id="status" class="sr-only" role="status" aria-live="polite" aria-atomic="true"></p>
    </main>
  </div>

  <dialog class="dialog-shell" id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
    <form class="dialog-card" method="dialog">
      <div class="dialog-copy">
        <span class="dialog-eyebrow">Delete from library</span>
        <h2 class="dialog-title" id="delete-title">Delete “Sunrise over the ridge”?</h2>
        <p id="delete-desc">This will permanently remove the image from your library. This action can't be undone.</p>
      </div>

      <div class="dialog-actions">
        <button type="submit" class="secondary" value="cancel" id="cancel-delete" autofocus>Cancel</button>
        <button type="submit" class="danger" value="delete">Delete image</button>
      </div>
    </form>
  </dialog>

  <script>
    const trigger = document.getElementById('open-delete-dialog');
    const dialog = document.getElementById('delete-dialog');
    const cancelButton = document.getElementById('cancel-delete');
    const previewCard = document.getElementById('preview-card');
    const emptyState = document.getElementById('empty-state');
    const status = document.getElementById('status');

    function openDeleteDialog() {
      if (dialog.open) {
        return;
      }

      if (typeof dialog.showModal === 'function') {
        dialog.showModal();
      } else {
        dialog.setAttribute('open', '');
      }

      trigger.setAttribute('aria-expanded', 'true');
      cancelButton.focus();
    }

    trigger.addEventListener('click', openDeleteDialog);

    dialog.addEventListener('close', () => {
      trigger.setAttribute('aria-expanded', 'false');

      if (dialog.returnValue === 'delete') {
        status.textContent = 'Image deleted from your library.';
        emptyState.hidden = false;
        emptyState.focus({ preventScroll: true });
        previewCard.hidden = true;
      }
    });
  </script>
</body>
</html>
