  const html = fs.readFileSync(path.join(process.cwd(), 'index.html'), 'utf8');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });
  const trigger = page.locator('.trigger');
  const dialog = page.locator('#delete-dialog');
  const empty = page.locator('#empty-state');
  await trigger.click();
  const open = await dialog.evaluate(el => el.open);
  await page.keyboard.press('Escape');
  const closed = await dialog.evaluate(el => !el.open);
  const focusBack = await page.evaluate(() => document.activeElement && document.activeElement.id === 'open-delete-dialog');
  await trigger.click();
  await page.locator('#delete-dialog .danger').click();
  await page.waitForTimeout(50);
  const deleted = await empty.evaluate(el => !el.hidden);
  console.log(JSON.stringify({ open, closed, focusBack, deleted }));
  await browser.close();
})();
